SELECT t.close_reason, COUNT(*) AS n, SUM(t.ret>0) AS gross_wins, SUM(t.ret>0 AND t.ret<0.20) AS win_below_020, SUM(t.ret>0 AND t.ret<0.15) AS win_below_015 FROM (SELECT p.close_reason, (p.exit_price-p.entry_price)/p.entry_price*100 AS ret FROM crypto_ai.paper_position p WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400)) t GROUP BY t.close_reason ORDER BY n DESC LIMIT 20;